import styles from "./show-list-item.module.less";
import Icon from "@/core/components/primitives/icon/icon";
import { DateHelper, multipleClassNames } from "@/core/helpers";
import { ListItemProps } from "./upcoming-block";
import Link from "@/core/components/primitives/link/link";
import Card from "@/core/components/primitives/card/card";
import Label from "@/core/components/primitives/label/label";
import { useTranslation } from "react-i18next";
import { SpokenText } from "@/core/components/primitives/spoken-text/spoken-text";
import AutoSizedText from "@/core/components/primitives/auto-sized-text/auto-sized-text";
import { useState } from "react";

type EventTimeResult = {
  displayEventTime: string;
  strikeThroughEventText?: string;
};

/**
 * Returns the event time texts to display for a given event.
 *
 * @returns An object containing:
 *   - displayEventTime: The text to display.
 *   - strikeThroughEventText (optional): The text to show with a strikethrough.
 *
 * @remarks
 * If both `eventTimesString` and `customDateText` are present and not hidden,
 * `eventTimesString` should be shown with a strikethrough.
 * Add `<SpokenText />` for screen readers, including the old and new time.
 * Wrap all the text in a `<span>` with `aria-hidden` to hide it from screen readers.
 * Wrap the strikethrough text in an `<s>` tag with `role="deletion"` for semantic and accessible markup.
 */
const getEventTime = ({
  eventTimesString,
  customDateText,
  customDateTime,
  hideEventDateAndOnlyShowCustomText,
}: Pick<ListItemProps, "customDateText" | "customDateTime" | "hideEventDateAndOnlyShowCustomText"> & {
  eventTimesString: string;
}): EventTimeResult => {
  if (!customDateText) {
    return { displayEventTime: eventTimesString };
  }

  const customDateAndTime = `${customDateText} ${customDateTime || ""}`;

  if (!eventTimesString || hideEventDateAndOnlyShowCustomText) return { displayEventTime: customDateAndTime };

  return {
    displayEventTime: customDateAndTime,
    strikeThroughEventText: eventTimesString,
  };
};

const EventTime = ({ displayEventTime, strikeThroughEventText }: EventTimeResult) => {
  const { t } = useTranslation();
  if (!strikeThroughEventText) return <>{displayEventTime}</>;

  return (
    <>
      <SpokenText
        text={t("upcomingBlockPreviousTime", {
          oldTime: strikeThroughEventText,
          newTime: displayEventTime,
        })}
      />
      <span aria-hidden>
        <s role="deletion">{strikeThroughEventText}</s> {displayEventTime}
      </span>
    </>
  );
};

export const ShowListItem = ({
  imageInList,
  title,
  shortDescriptionInList,
  pageLink,
  largeCardMobile,
  location,
  events,
  isTodayCard = false,
  label,
  labelComponentTheme,
  customDateText,
  customDateTime,
  hideEventDateAndOnlyShowCustomText,
  isEventDisplay,
}: ListItemProps & {
  isEventDisplay?: boolean;
}) => {
  const linkUrl = pageLink?.slug;
  const displayedDatesLimit = isTodayCard ? 3 : 1;

  const filteredEventStartTimes =
    events
      ?.map((item) => item.startDateAndTime)
      .filter((time) => DateHelper.isDateValid(time))
      .slice(0, displayedDatesLimit) ?? [];

  const eventTimesString = isTodayCard
    ? filteredEventStartTimes.map((time) => DateHelper.toStringTimeHHMM(time)).join(" & ")
    : filteredEventStartTimes.map((time) => DateHelper.toStringDDMMHHMM(time)).join(", ");

  const { t } = useTranslation();
  const todayLabel = t("today");

  const eventTimesStringWithToday =
    isEventDisplay && isTodayCard && eventTimesString ? `${todayLabel} ${eventTimesString}` : eventTimesString;

  const { displayEventTime, strikeThroughEventText } = getEventTime({
    eventTimesString: eventTimesStringWithToday,
    customDateText,
    customDateTime,
    hideEventDateAndOnlyShowCustomText,
  });

  const img = imageInList?.file.url;

  const [headlineWrapperRef, setHeadlineWrapperRef] = useState<HTMLDivElement | null>(null);
  const [locationWrapperRef, setLocationWrapperRef] = useState<HTMLDivElement | null>(null);
  const [eventTimeWrapperRef, setEventTimeWrapperRef] = useState<HTMLDivElement | null>(null);

  return (
    <Link internalLink={linkUrl}>
      {label && (
        <div
          className={multipleClassNames(styles.smallCardLabelWrapper, labelComponentTheme, "body-xs")}
          data-is-large-on-mobile={largeCardMobile}
        >
          <Label title={label} textSize="xs" />
        </div>
      )}
      <Card
        className={multipleClassNames(styles.wrapper, isEventDisplay && styles.eventDisplay)}
        data-is-large-on-mobile={largeCardMobile}
      >
        <div className={styles.imageWrapper}>
          {img && (
            <picture className={styles.image}>
              {/* Using the Contenful images API here instead of a GatsbyImage-query to maintain old behaviour */}
              <source srcSet={`${img}?w=310&q=70&fm=webp ${img}?w=600&q=70&fm=webp 2x`} type="image/webp" />
              <source srcSet={`${img}?w=310&q=70 ${img}?w=600&q=70 2x`} />
              {isEventDisplay ? <img src={img} alt={title} /> : <img src={`${img}?w=310&q=70`} alt={title} />}
            </picture>
          )}
          {label && (
            <div className={multipleClassNames(styles.largeCardLabelWrapper, labelComponentTheme)}>
              <Label title={label} />
            </div>
          )}
        </div>

        <div className={styles.textWrapper}>
          {title &&
            (isEventDisplay ? (
              <div className={styles.headline} ref={setHeadlineWrapperRef}>
                <AutoSizedText
                  wrapperElement={headlineWrapperRef}
                  text={title}
                  fontWeight="var(--common-font-weight-xl)"
                  justifyContent="flex-start"
                  padding="0"
                />
              </div>
            ) : (
              <h5 className={styles.headline}>{title}</h5>
            ))}
          {shortDescriptionInList && !isEventDisplay && (
            <p className={styles.shortDescription}>{shortDescriptionInList}</p>
          )}

          {location && (
            <div className={styles.iconAndText} ref={setLocationWrapperRef}>
              {isEventDisplay ? (
                <AutoSizedText
                  wrapperElement={locationWrapperRef}
                  text={location}
                  fontWeight="var(--common-font-weight-l)"
                  justifyContent="flex-start"
                  alignItems="flex-end"
                  icon="location"
                  padding="1 0"
                />
              ) : (
                <>
                  <Icon name="location" size="s" />
                  <span className="body-s">{location}</span>
                </>
              )}
            </div>
          )}

          {displayEventTime && (
            <div className={styles.iconAndText} ref={setEventTimeWrapperRef}>
              {isEventDisplay ? (
                <AutoSizedText
                  wrapperElement={eventTimeWrapperRef}
                  text={displayEventTime}
                  strikeThroughText={strikeThroughEventText}
                  fontWeight="var(--common-font-weight-l)"
                  justifyContent="flex-start"
                  alignItems="flex-start"
                  icon={isTodayCard ? "clock" : "calendar"}
                  padding="1 0"
                />
              ) : (
                <>
                  <Icon name="calendar" size="s" />
                  <span className="body-s">
                    <EventTime displayEventTime={displayEventTime} strikeThroughEventText={strikeThroughEventText} />
                  </span>
                </>
              )}
            </div>
          )}
        </div>
      </Card>
    </Link>
  );
};
