import { multipleClassNames } from "@/core/helpers";
import styles from "./label.module.less";

export type LabelProps = {
  title: string;
  textSize?: "xxs" | "xs" | "s" | "m" | "l";
};

const Label = ({ title, textSize = "s" }: LabelProps) => {
  return (
    <div className={styles.labelWrapper}>
      <span className={multipleClassNames(styles.label, `body-${textSize}`)}>{title}</span>
    </div>
  );
};

export default Label;
